from __future__ import annotations


# Kept in a separate module so the security-sensitive API wiring stays readable.
# The page never persists the evaluation token and never receives gold labels.
_D1_V2_CONSOLE_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>D1 AB100-V2 评测运行台</title>
<style>
:root{color-scheme:light;--ink:#172033;--muted:#60708a;--line:#d8dfeb;--blue:#1769e0;--red:#b42318;--green:#08783e;--bg:#f5f7fb}
*{box-sizing:border-box}body{font-family:system-ui,sans-serif;margin:0;background:var(--bg);color:var(--ink)}main{max-width:1180px;margin:28px auto;padding:0 18px 60px}
h1{margin-bottom:6px}.lead{color:var(--muted);margin-top:0}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;margin:14px 0;box-shadow:0 4px 18px #24324a0c}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}label{font-weight:600}input,select,textarea{border:1px solid #aeb9ca;border-radius:8px;padding:9px;font:inherit}input[type=password],input.wide{min-width:360px}textarea{width:100%;min-height:72px;resize:vertical}
button{border:0;border-radius:8px;background:var(--blue);color:#fff;padding:10px 14px;cursor:pointer;font-weight:650}button.secondary{background:#52647f}button.danger{background:var(--red)}button:disabled{opacity:.45;cursor:not-allowed}
.meta{color:var(--muted);font-size:13px}.ok{color:var(--green)}.bad{color:var(--red)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px}.metric{border:1px solid var(--line);padding:12px;border-radius:10px}.metric strong{display:block;font-size:20px;margin-top:4px}
.tableWrap{overflow:auto;margin-top:12px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid var(--line);padding:8px;text-align:left;white-space:nowrap}th{background:#f5f7fb}hr{border:0;border-top:1px solid var(--line);margin:20px 0}
.review{border-top:1px solid var(--line);padding:16px 0}.review:first-child{border-top:0}.quote{padding:10px;background:#f7f9fc;border-radius:8px;margin:7px 0;white-space:pre-wrap}.guide{border-left:4px solid var(--blue);padding:10px 14px;background:#f3f7ff;border-radius:8px}.attest{display:grid;gap:8px;margin:14px 0}.attest label{font-weight:500}.actions{margin-top:12px}pre{white-space:pre-wrap;word-break:break-word;background:#111827;color:#e5ecf7;padding:14px;border-radius:10px;max-height:560px;overflow:auto}.hidden{display:none}
</style></head><body><main>
<h1>D1 AB100-V2 评测运行台</h1>
<p class="lead">隔离真实模型评测；正式业务写回始终关闭。令牌仅保存在当前页面内存，刷新后清除。</p>
<section class="card"><div class="row"><label>评测令牌 <input id="token" type="password" autocomplete="off"></label><button id="load">加载状态</button></div><p id="message" class="meta">请先登录并输入评测令牌。</p></section>
<section id="manifestCard" class="card hidden"><h2>冻结清单与门禁</h2><div id="manifest" class="grid"></div></section>
<section id="reviewCard" class="card hidden"><h2 id="reviewTitle">启动前固定 10 条独立复核</h2><p class="meta">页面不显示金标准、前次复核答案、合成故障标签、预期曝光或模型结果。每次提交均写入新证据文件，不能修改或覆盖。</p><div id="relationGuide" class="guide"></div><p id="reviewAttempt" class="meta"></p><div id="reviewItems"></div><div class="attest"><label><input id="attestHuman" type="checkbox"> 我确认复核答案由当前真人复核人逐条独立判断，并非 AI 生成或代填。</label><label><input id="attestIndependent" type="checkbox"> 我确认复核人不负责执行本次模型评测。</label><label><input id="attestGold" type="checkbox"> 我确认复核人未看过冻结金标准。</label><label><input id="attestPrior" type="checkbox"> 我确认复核人未看过前次复核的逐条答案。</label></div><button id="submitReview">一次性提交 10 条复核</button></section>
<section id="runCard" class="card hidden"><h2>顺序执行</h2><p class="meta">后端强制：单例成功 → 固定十例预检 → 人工 go/no-go → 正式百例。预检不使用临时效果阈值。</p><div class="row"><label>单例 <select id="singleCase"></select></label><button id="single">运行单例</button><button id="precheck" disabled>运行固定 10 例</button><button id="formal" disabled>运行正式 100 例</button></div><div class="actions row"><button id="refreshRuns" class="secondary">刷新运行状态</button><button id="resume" class="danger" disabled>恢复中断批次</button></div><div id="runs"></div></section>
<section id="decisionCard" class="card hidden"><h2>预检人工 go/no-go</h2><p class="meta">请先加载紧凑回执，再人工核对 10/10 合法回执、无最终技术失败、A/B 输入一致、曝光范围和 repair 合同正确、无安全边界破坏。</p><div class="row"><button id="precheckReceipts" class="secondary">加载 10 条紧凑回执</button><span id="precheckReceiptStatus" class="meta">尚未加载。</span></div><div id="precheckReceiptSummary"></div><textarea id="decisionNote" placeholder="填写人工检查依据（至少 3 字）"></textarea><div class="row"><button id="go" disabled>确认 GO</button><button id="nogo" class="danger" disabled>确认 NO-GO</button></div></section>
<section id="evidenceCard" class="card hidden"><h2>正式证据</h2><p class="meta">重复运行固定、预注册且与启动复核不重叠的 20 条；只能由原执行账户启动。</p><div class="row"><button id="repeat" disabled>运行固定 20 条重复实验</button><button id="resumeRepeat" class="danger" disabled>恢复重复实验</button></div><hr><h3>独立正式盲审</h3><p class="meta">请由不同认证账户通过安全渠道取得正式批次 ID。材料不含模型结果或金标准；盲审账户不需要拥有该批次。标签仍按“先判断规则是否适用，再判断同一目标声明是否矛盾”的定义填写。</p><div class="row"><label>正式批次 ID <input id="blindRunId" class="wide" autocomplete="off" placeholder="D1V2RUN_…"></label><button id="blind">加载固定 20 条盲审材料</button></div><div id="blindItems"></div><button id="submitBlind" class="hidden">一次性提交 20 条盲审</button></section>
<section class="card"><h2>紧凑结果</h2><pre id="output">尚未加载。</pre></section>
<script>
const $=s=>document.querySelector(s), token=()=>$('#token').value.trim(), headers=(json=false)=>{const h={'X-Accountability-Evaluation-Token':token()};if(json)h['Content-Type']='application/json';return h};
let manifest=null,startupReviewPackage=null,runs=[],activeRun=null,singleRun=null,precheckRun=null,formalRun=null,pollTimer=null,precheckEvidenceRunId=null,blindReviewRunId=null;
function msg(t,bad=false){$('#message').textContent=t;$('#message').className=bad?'meta bad':'meta'}
async function api(url,opt={}){const r=await fetch(url,{...opt,headers:{...headers(Boolean(opt.body)),...(opt.headers||{})}});let d;try{d=await r.json()}catch{d={detail:await r.text()}}if(!r.ok)throw new Error(d.detail||JSON.stringify(d));return d}
function metric(label,value,cls=''){return `<div class="metric"><span class="meta">${label}</span><strong class="${cls}">${value}</strong></div>`}
function renderManifest(){const m=manifest;const attempt=m.human_review_active_attempt_number||'未提交';$('#manifest').innerHTML=metric('数据集',m.dataset_id)+metric('版本',m.version)+metric('SHA-256',m.file_sha256.slice(0,16)+'…')+metric('独立复核',`${m.human_review_approved_count}/${m.human_review_required_count}`,m.human_review_passed?'ok':'bad')+metric('当前复核尝试',attempt)+metric('运行模式',m.runtime_mode,m.runtime_mode==='live'?'ok':'bad')+metric('正式写回',m.formal_environment_write_allowed?'开启':'关闭',m.formal_environment_write_allowed?'bad':'ok');$('#manifestCard').classList.remove('hidden')}
function classifyRuns(){singleRun=runs.find(x=>x.purpose==='single_trace'&&x.status==='completed'&&x.coverage_valid)||null;precheckRun=runs.find(x=>x.purpose==='precheck')||null;formalRun=runs.find(x=>x.purpose==='formal')||null;activeRun=runs.find(x=>['queued','running','interrupted'].includes(x.status))||formalRun||precheckRun||singleRun;const busy=runs.some(x=>['queued','running'].includes(x.status)||['queued','running'].includes(x.repeat_status));$('#single').disabled=busy||!manifest.execution_allowed;$('#precheck').disabled=busy||!singleRun||Boolean(precheckRun);$('#formal').disabled=busy||!precheckRun||precheckRun.status!=='completed'||precheckRun.precheck_decision!=='go'||Boolean(formalRun);$('#resume').disabled=!activeRun||!activeRun.resumable;const decisionPending=Boolean(precheckRun&&precheckRun.status==='completed'&&!precheckRun.precheck_decision);$('#decisionCard').classList.toggle('hidden',!decisionPending);$('#precheckReceipts').disabled=!decisionPending;const evidenceLoaded=decisionPending&&precheckEvidenceRunId===precheckRun.run_id;$('#go').disabled=!evidenceLoaded;$('#nogo').disabled=!evidenceLoaded;$('#repeat').disabled=busy||!formalRun||formalRun.status!=='completed'||formalRun.repeat_status!=='not_started';$('#resumeRepeat').disabled=!formalRun||!formalRun.repeat_resumable;if(formalRun&&formalRun.status==='completed'&&!$('#blindRunId').value.trim())$('#blindRunId').value=formalRun.run_id}
function renderRuns(){classifyRuns();$('#runs').innerHTML=runs.length?runs.map(x=>`<div class="metric"><b>${escapeHtml(x.purpose)}</b> · ${escapeHtml(x.run_id)}<br><span class="meta">${escapeHtml(x.status)} · ${Number(x.completed_case_count)}/${Number(x.total_case_count)} · 技术失败 ${Number(x.technical_failure_count)} · 恢复 ${Number(x.resume_count)}${x.repeat_status?` · 重复 ${escapeHtml(x.repeat_status)} ${Number(x.repeat_completed_case_count||0)}/20`:''}</span></div>`).join(''):'<p class="meta">暂无批次。</p>';const busy=runs.some(x=>['queued','running'].includes(x.status)||['queued','running'].includes(x.repeat_status));clearTimeout(pollTimer);if(busy)pollTimer=setTimeout(loadRuns,2500)}
async function loadRuns(){runs=(await api('/api/v1/internal-eval/d1-v2/batches')).items;renderRuns();if(formalRun&&formalRun.score_available){try{$('#output').textContent=JSON.stringify(await api(`/api/v1/internal-eval/d1-v2/batches/${formalRun.run_id}/score`),null,2)}catch{}}}
async function loadReview(){const p=await api('/api/v1/internal-eval/d1-v2/independent-review');startupReviewPackage=p;const d=p.relation_definitions;$('#reviewTitle').textContent=`启动前固定 10 条独立复核 · 第 ${p.attempt_number} 次`;$('#reviewAttempt').textContent=p.attempt_number===2?'第一次失败证据已封存。本次必须由不同认证账户、未见金标准和前次逐条答案的新真人复核。':'这是第一次复核；必须由非评测执行人员独立完成。';$('#relationGuide').innerHTML=`<b>统一判定顺序</b><ol><li>先判断两条证据是否形成目标冲突规则要处理的同一目标声明；若否，选择“不适用”。</li><li>只有同一目标声明适用该规则时，才判断“矛盾”或“相容”。</li></ol><b>矛盾：</b>${escapeHtml(d.contradiction)}<br><b>相容：</b>${escapeHtml(d.compatible)}<br><b>不适用：</b>${escapeHtml(d.not_applicable)}`;$('#reviewItems').innerHTML=p.items.map((x,i)=>reviewHtml(x,i,'pre')).join('');$('#submitReview').disabled=!p.submission_allowed;$('#reviewCard').classList.remove('hidden')}
function reviewHtml(x,i,prefix){return `<div class="review" data-case="${x.case_id}"><b>${i+1}. ${x.case_id}</b><div class="quote"><b>问题：</b>${escapeHtml(x.prompt)}</div><div class="quote"><b>主张：</b>${escapeHtml(x.claim_text)}</div><div class="quote"><b>证据 A：</b>${escapeHtml(x.evidence_a_text)}</div><div class="quote"><b>证据 B：</b>${escapeHtml(x.evidence_b_text)}</div><div class="row"><label>规则关系 <select class="relation"><option value="">请选择</option><option value="contradiction">矛盾（同一目标声明，不能同时成立）</option><option value="compatible">相容（同一目标声明，可以同时成立）</option><option value="not_applicable">不适用（未形成规则目标声明）</option></select></label><label>复核人 <input class="name" maxlength="200"></label></div><textarea class="notes" placeholder="独立判断依据（至少 3 字）"></textarea></div>`}
function collect(root){return [...root.querySelectorAll('.review')].map(x=>({case_id:x.dataset.case,reviewer_relation:x.querySelector('.relation').value,reviewer_name:x.querySelector('.name').value.trim(),review_notes:x.querySelector('.notes').value.trim()}))}
function escapeHtml(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('#load').onclick=async()=>{try{manifest=await api('/api/v1/internal-eval/d1-v2/manifest');renderManifest();const cases=manifest.human_review_sample_case_ids;$('#singleCase').innerHTML=cases.map(x=>`<option>${escapeHtml(x)}</option>`).join('');$('#runCard').classList.remove('hidden');$('#evidenceCard').classList.remove('hidden');if(!manifest.human_review_passed&&(manifest.human_review_attempt_count===0||manifest.human_review_retry_allowed))await loadReview();else $('#reviewCard').classList.add('hidden');await loadRuns();msg(manifest.execution_allowed?'已加载，可按顺序执行。':`执行门禁：${manifest.execution_block_reason}`)}catch(e){msg('加载失败：'+e.message,true)}};
$('#submitReview').onclick=async()=>{if(!startupReviewPackage){msg('请先加载复核材料。',true);return}const attested=$('#attestHuman').checked&&$('#attestIndependent').checked&&$('#attestGold').checked&&$('#attestPrior').checked;if(!attested){msg('必须由真人复核人逐项确认四项独立性声明。',true);return}if(!confirm(`第 ${startupReviewPackage.attempt_number} 次提交将永久封存且不可修改，确认由当前真人独立完成？`))return;try{manifest=await api('/api/v1/internal-eval/d1-v2/independent-review',{method:'POST',body:JSON.stringify({attempt_number:startupReviewPackage.attempt_number,human_reviewer:true,independent_review:true,gold_labels_not_seen:true,prior_review_decisions_not_seen:true,items:collect($('#reviewItems'))})});renderManifest();$('#reviewCard').classList.add('hidden');msg(manifest.human_review_passed?'独立复核 10/10 与冻结金标准一致，请由不同账户执行评测。':manifest.human_review_retry_allowed?'独立复核存在分歧；失败证据已封存，可由新的真人账户进行最后一次复核。':'独立复核存在分歧，评测保持阻断。',!manifest.human_review_passed)}catch(e){msg('复核提交失败：'+e.message,true)}};
async function start(purpose,ids,prerequisite){const d=await api('/api/v1/internal-eval/d1-v2/batches',{method:'POST',body:JSON.stringify({purpose,case_ids:ids,prerequisite_run_id:prerequisite||null})});$('#output').textContent=JSON.stringify(d,null,2);await loadRuns()}
$('#single').onclick=async()=>{try{await start('single_trace',[$('#singleCase').value],null)}catch(e){msg(e.message,true)}};$('#precheck').onclick=async()=>{try{await start('precheck',manifest.human_review_sample_case_ids,singleRun.run_id)}catch(e){msg(e.message,true)}};$('#formal').onclick=async()=>{if(!confirm('确认启动 100 对真实模型正式评测？'))return;try{const ids=Array.from({length:100},(_,i)=>`EVO-D1-V2-${String(i+1).padStart(3,'0')}`);await start('formal',ids,precheckRun.run_id)}catch(e){msg(e.message,true)}};
$('#refreshRuns').onclick=loadRuns;$('#resume').onclick=async()=>{try{await api(`/api/v1/internal-eval/d1-v2/batches/${activeRun.run_id}/resume`,{method:'POST'});await loadRuns()}catch(e){msg(e.message,true)}};
$('#precheckReceipts').onclick=async()=>{if(!precheckRun)return;try{const d=await api(`/api/v1/internal-eval/d1-v2/batches/${encodeURIComponent(precheckRun.run_id)}/receipts`);const rows=d.receipts||[],errors=d.technical_errors||[];const validCount=rows.filter(x=>x.validation&&x.validation.valid&&x.validation.repair_contract_valid).length;const digestMatchCount=rows.filter(x=>{const arms=x.arms||[];return arms.length===2&&arms[0].input_digest===arms[1].input_digest}).length;$('#precheckReceiptSummary').innerHTML=metric('紧凑回执',`${rows.length}/10`,rows.length===10?'ok':'bad')+metric('合同有效',`${validCount}/10`,validCount===10?'ok':'bad')+metric('A/B 输入一致',`${digestMatchCount}/10`,digestMatchCount===10?'ok':'bad')+metric('技术错误尝试',errors.length,errors.length===0?'ok':'bad')+`<div class="tableWrap"><table><thead><tr><th>案例</th><th>顺序</th><th>尝试</th><th>A 曝光</th><th>B 曝光</th><th>输入一致</th><th>合同</th></tr></thead><tbody>${rows.map(x=>{const arms=x.arms||[],a=arms.find(v=>v.arm==='A')||{},b=arms.find(v=>v.arm==='B')||{},same=Boolean(a.input_digest&&a.input_digest===b.input_digest),valid=Boolean(x.validation&&x.validation.valid&&x.validation.repair_contract_valid);return `<tr><td>${escapeHtml(x.case_id)}</td><td>${escapeHtml(x.pair_order)}</td><td>${Number(x.attempt)}</td><td>${Boolean(a.rule_exposed)}</td><td>${Boolean(b.rule_exposed)}</td><td class="${same?'ok':'bad'}">${same?'是':'否'}</td><td class="${valid?'ok':'bad'}">${valid?'有效':'无效'}</td></tr>`}).join('')}</tbody></table></div>`;$('#precheckReceiptStatus').textContent='紧凑回执已加载，请人工核对后填写依据。';precheckEvidenceRunId=precheckRun.run_id;$('#go').disabled=false;$('#nogo').disabled=false;$('#output').textContent=JSON.stringify(d,null,2)}catch(e){precheckEvidenceRunId=null;$('#go').disabled=true;$('#nogo').disabled=true;msg('预检回执加载失败：'+e.message,true)}};
async function decide(decision){try{await api(`/api/v1/internal-eval/d1-v2/batches/${precheckRun.run_id}/precheck-decision`,{method:'POST',body:JSON.stringify({decision,note:$('#decisionNote').value})});await loadRuns()}catch(e){msg(e.message,true)}}$('#go').onclick=()=>decide('go');$('#nogo').onclick=()=>decide('no_go');
$('#repeat').onclick=async()=>{try{await api(`/api/v1/internal-eval/d1-v2/batches/${formalRun.run_id}/repeatability`,{method:'POST'});await loadRuns()}catch(e){msg(e.message,true)}};$('#resumeRepeat').onclick=async()=>{try{await api(`/api/v1/internal-eval/d1-v2/batches/${formalRun.run_id}/repeatability/resume`,{method:'POST'});await loadRuns()}catch(e){msg(e.message,true)}};
$('#blind').onclick=async()=>{const runId=$('#blindRunId').value.trim();if(!/^D1V2RUN_[0-9a-f]{32}$/.test(runId)){msg('请输入有效的正式批次 ID。',true);return}try{const p=await api(`/api/v1/internal-eval/d1-v2/batches/${encodeURIComponent(runId)}/blind-review`);blindReviewRunId=runId;$('#blindItems').innerHTML=p.items.map((x,i)=>reviewHtml(x,i,'formal')).join('');$('#submitBlind').classList.remove('hidden');$('#submitBlind').disabled=false;msg('已加载固定 20 条盲审材料；未包含模型结果或金标准。')}catch(e){blindReviewRunId=null;msg(e.message,true)}};
$('#submitBlind').onclick=async()=>{if(!blindReviewRunId){msg('请先加载正式盲审材料。',true);return}if(!confirm('正式盲审提交后不可修改，确认提交？'))return;try{const d=await api(`/api/v1/internal-eval/d1-v2/batches/${encodeURIComponent(blindReviewRunId)}/blind-review`,{method:'POST',body:JSON.stringify({items:collect($('#blindItems'))})});$('#output').textContent=JSON.stringify(d,null,2);$('#submitBlind').disabled=true;await loadRuns()}catch(e){msg(e.message,true)}};
</script></main></body></html>"""


def d1_v2_console_html() -> str:
    return _D1_V2_CONSOLE_HTML
